#include <iiGUI/iiGUI.h>
#include <iostream>
#include <stdexcept>
using namespace ii;
namespace {
template<class T>T take(core::Result<T> r){if(!r)throw std::runtime_error(r.error().message);return std::move(*r);}
void good(core::Result<void> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}}
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
struct Scope final {int& retired;std::shared_ptr<gui::ColorPickerModel> model=std::make_shared<gui::ColorPickerModel>();explicit Scope(int& n):retired(n){}~Scope(){++retired;}};
void lifecycle(bool repeat){
    gui::Host host;gui::Widget popup,old;int builds=0,retired=0,closed=0;std::weak_ptr<Scope> watched;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& b)->core::Result<void>{auto root=take(b.vstack({},"root"));take(b.button(root,"anchor",{.text="Open"}));popup=take(b.popover(root,"popup",{.width=260,.height=230},{.closed=[&]{++closed;check(watched.expired(),"Content scope outlived closed callback");}}));return popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{++builds;auto scope=std::make_shared<Scope>(retired);watched=scope;good(w.retain(scope));auto root=take(w.vstack({},"content"));for(int i=0;i<8;++i)take(w.button(root,"b"+std::to_string(i),{.text="Activation"}));return {};});}));
        check(!popup.popup_content(),"Closed popup exposed a content item");good(popup.open_at(50,60));old=take(popup.popup_content("b0"));auto first=take(old.snapshot()).id;good(popup.open_at(70,60));check(builds==1,"Reposition rebuilt an active content scope");good(popup.close_popup());check(retired==1&&!old.activate(),"Old content survived close");good(popup.open_at(50,60));check(take(take(popup.popup_content("b0")).snapshot()).id!=first&&!old.snapshot(),"Reopen reused a stale activation identity");good(popup.close_popup());
        if(repeat)for(int i=0;i<500;++i){good(popup.open_at(50,60));check(take(m.snapshot()).size()==12,"Closed activations accumulated in the live tree");good(popup.close_popup());}
        check(builds==retired&&closed==retired&&watched.expired(),"Content scopes did not retire exactly once");good(host.request_close());}}));
}
void input(){
    gui::Host host;gui::Widget popup;int clicked=0,escapes=0;std::string value;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));take(b.button(root,"outside",{.text="Outside"}));popup=take(b.popover(root,"popup",{.width=260,.height=180,.modal=true}));return popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{auto root=take(w.vstack({},"form"));take(w.input_field(root,"field",{},[&](std::string s){value=std::move(s);}));take(w.button(root,"go",{.text="Go"},[&]{++clicked;}));return {};});}));good(popup.open_at(40,70));auto field=take(popup.popup_content("field"));check(take(field.snapshot()).focused,"Content did not receive initial focus");good(m.dispatch_input({.kind=gui::WidgetInputKind::text,.text="native"}));check(value=="native","Text did not reach activation");good(m.dispatch_input({.kind=gui::WidgetInputKind::key_down,.key=gui::WidgetKey::tab}));auto go=take(popup.popup_content("go"));check(take(go.snapshot()).focused,"Tab did not move within activation");auto r=take(go.snapshot()).bounds;good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_down,.x=r.x+3,.y=r.y+3}));good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_up,.x=r.x+3,.y=r.y+3}));check(clicked==1,"Pointer coordinates did not route to activation");good(go.set_escape_action([&]{++escapes;}));good(m.dispatch_input({.kind=gui::WidgetInputKind::key_down,.key=gui::WidgetKey::escape}));check(escapes==1&&take(popup.snapshot()).opened,"Parent bypassed child Escape");good(go.set_escape_action({}));good(m.dispatch_input({.kind=gui::WidgetInputKind::key_down,.key=gui::WidgetKey::escape}));check(!take(popup.snapshot()).opened,"Unhandled Escape did not close parent");good(host.request_close());}}));
}
void rendering(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget popup;auto m=take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup",{.width=180,.height=150}));return popup.set_popup_content([](gui::WidgetBuilder&w)->core::Result<void>{auto model=std::make_shared<gui::ColorPickerModel>();if(auto r=model->set_color({1,0,0,1});!r)return r;auto root=w.vstack({},"content");if(!root)return std::unexpected(root.error());auto field=w.color_surface(*root,"domain",{.model=model,.field=gui::ColorField::saturation_brightness,.width=100,.height=100});if(!field)return std::unexpected(field.error());return {};});}));good(popup.open_at(60,70));auto pixels=take(host.capture_canvas());auto r=take(take(popup.popup_content("domain")).snapshot()).bounds;auto size=take(host.snapshot()).size;auto x=unsigned((r.x+r.width*.5)/size.width*pixels.width),y=unsigned((r.y+r.height*.5)/size.height*pixels.height),at=(y*pixels.width+x)*4;check(pixels.rgba[at]>100&&pixels.rgba[at]<160&&pixels.rgba[at+1]>35&&pixels.rgba[at+1]<95,"Embedded native color content did not reach Metal");good(popup.close_popup());check(take(host.capture_canvas()).rgba!=pixels.rgba,"Retired content remained in the GPU scene");good(host.request_close());}}));
}
void failure(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget popup;auto m=take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup"));return popup.set_popup_content([](gui::WidgetBuilder&w)->core::Result<void>{auto r=w.label({},"partial",{.text="Not published"});if(!r)return std::unexpected(r.error());return core::fail(core::ErrorCode::invalid_argument,"factory failure");});}));check(!popup.open_at(30,40)&&!take(popup.snapshot()).opened&&take(m.snapshot()).size()==2,"Failed activation leaked or replaced owner content");int retired=0;good(popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{auto scope=std::make_shared<Scope>(retired);good(w.retain(scope));throw std::runtime_error("factory exception");}));bool caught=false;try{(void)popup.open_at(30,40);}catch(const std::runtime_error&){caught=true;}check(caught&&retired==1&&!take(popup.snapshot()).opened,"Throwing factory leaked scope or published content");good(popup.set_popup_content([](gui::WidgetBuilder&w)->core::Result<void>{auto r=w.label({},"ok",{.text="Retry"});if(!r)return std::unexpected(r.error());return {};}));good(popup.open_at(30,40));check(!popup.set_popup_content({}),"Factory changed during an active activation");good(popup.close_popup());good(host.request_close());}}));
}
void nesting(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget popup;int clicks=0;auto m=take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup",{.width=220,.height=150}));return popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{auto root=take(w.vstack({},"body"));take(w.button(root,"anchor",{.text="Menu"}));auto menu=take(w.menu(root,"menu"));take(w.menu_item(menu,"entry",{.label="Nested",.icon_name="",.show_icon_slot=false,.has_child_items=false},[&]{++clicks;}));return {};});}));good(popup.open_at(60,70));auto menu=take(popup.popup_content("menu")),anchor=take(popup.popup_content("anchor"));good(menu.open_for(anchor,180,0));auto item=take(popup.popup_content("entry"));auto r=take(item.snapshot()).bounds;check(r.x>take(popup.snapshot()).bounds.x+take(popup.snapshot()).bounds.width-30,"Nested popup did not overflow parent");good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_down,.x=r.x+3,.y=r.y+3}));good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_up,.x=r.x+3,.y=r.y+3}));check(clicks==1&&take(popup.snapshot()).opened&&!take(menu.snapshot()).opened,"Overflow nested menu input dismissed parent or missed item");good(menu.open_for(anchor,180,0));good(m.dispatch_input({.kind=gui::WidgetInputKind::key_down,.key=gui::WidgetKey::escape}));check(!take(menu.snapshot()).opened&&take(popup.snapshot()).opened,"Escape closed parent before nested menu");good(popup.close_popup());check(!item.snapshot(),"Nested handle survived activation close");good(host.request_close());}}));
}
void limits(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget popup;auto m=take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup"));return popup.set_popup_content([](gui::WidgetBuilder&w)->core::Result<void>{auto root=take(w.vstack({},"body"));for(int i=0;i<4096;++i){auto child=w.label(root,std::to_string(i));if(!child)return std::unexpected(child.error());}return {};});}));auto result=popup.open_at(20,20);check(!result&&result.error().code==core::ErrorCode::out_of_range&&take(m.snapshot()).size()==2,"Candidate exceeded shared active-node budget or leaked failed content");good(popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{check(!popup.open_at(20,20),"Reentrant factory admitted another activation");auto r=w.label({},"ok");if(!r)return std::unexpected(r.error());return {};}));good(popup.open_at(20,20));good(popup.close_popup());good(host.request_close());}}));
}
void reentrant(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget popup;int builds=0,closes=0;bool reopen=false;auto m=take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup",{.width=200,.height=130},{.closed=[&]{++closes;if(reopen){reopen=false;good(popup.open_at(80,80));}}}));return popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{++builds;auto r=w.button({},"close",{.text="Close"},[&]{good(popup.close_popup());});if(!r)return std::unexpected(r.error());return {};});}));good(popup.open_at(80,80));auto old=take(popup.popup_content("close"));auto id=take(old.snapshot()).id;reopen=true;good(m.dispatch_input({.kind=gui::WidgetInputKind::activate,.target=id}));check(builds==2&&closes==1&&take(popup.snapshot()).opened&&!old.activate(),"Content close/reopen reached stale generation");check(!m.dispatch_input({.kind=gui::WidgetInputKind::activate,.target=id})&&closes==1,"Retired AX target reached replacement activation");good(popup.close_popup());good(host.request_close());}}));
}
void teardown(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget root,popup,field;int late=0;take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup",{}, {.closed=[&]{++late;}}));return popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{field=take(w.input_field({},"field",{.commit_on_focus_loss=true},{},[&]{good(host.unmount_widgets());}));return {};});}));good(popup.open_at(30,40));good(root.set_visible(false));check(late==0&&!field.snapshot(),"Hide invoked callbacks after child blur retired the owner");good(host.request_close());}}));
}
void active_use(){
    gui::Host host;good(host.run({.opened=[&]{gui::Widget popup,button;int retired=0,closed=0;std::weak_ptr<Scope> watched;take(host.mount_widgets([&](gui::WidgetBuilder&b)->core::Result<void>{auto root=take(b.vstack({},"root"));popup=take(b.popover(root,"popup",{}, {.closed=[&]{++closed;check(!popup.popup_content()&&!watched.expired(),"Closed notification must revoke ownership without destroying a scope still executing its callback");}}));return popup.set_popup_content([&](gui::WidgetBuilder&w)->core::Result<void>{auto scope=std::make_shared<Scope>(retired);watched=scope;good(w.retain(scope));button=take(w.button({},"button",{.text="Retire active use"},[&,scope]{good(popup.close_popup());check(!button.snapshot()&&retired==0,"Active callback was destroyed or stale handle remained usable");}));return {};});}));good(popup.open_at(30,40));good(button.activate());check(closed==1&&retired==1&&watched.expired(),"Active callback captures did not retire once after return");good(host.request_close());}}));
}
}
int main(int argc,char**argv){try{std::string_view name=argc>1?argv[1]:"lifecycle";if(name=="lifecycle")lifecycle(false);else if(name=="reuse")lifecycle(true);else if(name=="input")input();else if(name=="rendering")rendering();else if(name=="failure")failure();else if(name=="nesting")nesting();else if(name=="limits")limits();else if(name=="reentrant")reentrant();else if(name=="teardown")teardown();else if(name=="active_use")active_use();else throw std::runtime_error("Unknown popup content case");std::cout<<"POPUP_CONTENT_OK "<<name<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
